CREATE OR REPLACE FUNCTION public.create_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, username) VALUES (NEW.id, coalesce(nullif(NEW.raw_user_meta_data->>'full_name', ''), 'عضو جديد'), 'member_' || substring(replace(NEW.id::text, '-', '') FROM 1 FOR 20)); INSERT INTO public.member_xp(user_id) VALUES (NEW.id); RETURN NEW; END $$;